from pathlib import Path
import json,base64,html,shutil
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/v6_result_to_draw_20261011'

def table(frame,percent=(),decimals=()):
    q=frame.copy()
    for c in percent:
        if c in q:q[c]=q[c].map(lambda v:'' if pd.isna(v) else f'{v:.1%}')
    for c in decimals:
        if c in q:q[c]=q[c].map(lambda v:'' if pd.isna(v) else f'{v:.4f}')
    return q.to_html(index=False,border=0,escape=True)

def chart(name):
    plt.tight_layout();p=OUT/'plots'/f'{name}.png';plt.savefig(p,dpi=160,bbox_inches='tight');plt.close()
    return '<img alt="'+name+'" src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'">'

def main():
    (OUT/'plots').mkdir(exist_ok=True)
    summary=json.loads((OUT/'completion_summary.json').read_text());reg=json.loads((ROOT/'assets/manifest.json').read_text())
    prep=json.loads((OUT/'preparation_summary.json').read_text())
    mainm=pd.read_csv(OUT/'metrics_comparison.csv');test=mainm[mainm.partition.eq('test')]
    nested=json.loads((OUT/'nested_aggregate.json').read_text());nm=pd.DataFrame([{'family':f,**m} for f,m in nested.items()])
    iterations=pd.read_csv(OUT/'all_iterations.csv');bt=pd.read_csv(OUT/'nested_backtesting_metrics.csv')
    incumbent=pd.read_csv(OUT/'incumbent_comparison.csv') if (OUT/'incumbent_comparison.csv').exists() else pd.DataFrame()
    eda=pd.read_csv(OUT/'eda_variables.csv')
    selected=summary['selected_family'];m=summary['test']
    decision='Cumple los gates de desarrollo y prueba independiente' if summary['production_approved'] else 'Candidato de investigación con señales operativas deshabilitadas'
    executive=f"<p class='lead'>{decision}. El modelo seleccionado antes de abrir la prueba fue <strong>{selected}</strong>. En prueba independiente obtuvo <strong>precisión {m['precision']:.1%}</strong>, recall {m['recall']:.1%} y F1 {m['f1']:.1%}, con {int(m['tp']+m['fp'])} señales sobre {m['rows']} snapshots.</p>"
    plots=[]
    fig,ax=plt.subplots(figsize=(10,4));pos=np.arange(len(test))
    ax.bar(pos-.18,test.precision,.36,label='Precisión');ax.bar(pos+.18,test.recall,.36,label='Recall')
    ax.axhline(.5,color='#ad2a35',ls='--',label='Precisión >50%');ax.axhline(.25,color='#777',ls=':',label='Recall >25%')
    ax.set_xticks(pos,test.family,rotation=25,ha='right');ax.set_ylim(0,1);ax.yaxis.set_major_formatter(matplotlib.ticker.PercentFormatter(1));ax.legend(fontsize=8);ax.set_title('Prueba temporal independiente con umbrales congelados');plots.append(chart('test_metrics'))
    fig,ax=plt.subplots(figsize=(10,4))
    for f,g in bt.groupby('family'):ax.plot(g.fold,g.precision,marker='o',label=f)
    ax.axhline(.5,color='#ad2a35',ls='--');ax.yaxis.set_major_formatter(matplotlib.ticker.PercentFormatter(1));ax.set_ylim(0,1);ax.set_xticks(range(1,6));ax.set_xlabel('Fold temporal');ax.set_ylabel('Precisión');ax.legend(ncol=4,fontsize=8);plots.append(chart('nested_precision'))
    fig,ax=plt.subplots(figsize=(10,4));p=pd.read_csv(OUT/'partitions.csv').set_index('partition').reindex(['train','calibration','validation','test']);ax.bar(p.index,p.prevalence,color='#355f89');ax.yaxis.set_major_formatter(matplotlib.ticker.PercentFormatter(1));ax.set_title('Prevalencia real sin balanceo de validación o test');plots.append(chart('prevalence'))
    top=pd.read_csv(OUT/'feature_audits/main_cycle3.csv').dropna(subset=['spearman_target']).assign(abs_rho=lambda z:z.spearman_target.abs()).nlargest(16,'abs_rho')
    fig,ax=plt.subplots(figsize=(10,6));ax.barh(top.feature[::-1],top.spearman_target[::-1],color='#355f89');ax.set_xlabel('Spearman contra el target, sólo entrenamiento');plots.append(chart('target_correlations'))
    replay=pd.read_csv(OUT/'backtesting_base_completa.csv',low_memory=False)
    mask=(replay.v6_partition.eq('test')&replay.v6_training_cohort)
    pprob=replay.loc[mask,f'v6_{selected}_probability'];yy=replay.loc[mask,'result_to_draw'].astype(bool)
    caldata=pd.DataFrame({'p':pprob,'y':yy.astype(int)});caldata['bin']=pd.cut(caldata.p,np.linspace(0,1,11),include_lowest=True)
    curve=caldata.groupby('bin',observed=True).agg(probability=('p','mean'),observed=('y','mean'),rows=('y','size')).reset_index()
    fig,ax=plt.subplots(figsize=(6,5));ax.plot([0,1],[0,1],ls='--',color='#888');ax.plot(curve.probability,curve.observed,'o-',color='#355f89');ax.set(xlim=(0,1),ylim=(0,1),xlabel='Probabilidad media',ylabel='Proporción observada',title='Calibración del campeón en prueba');plots.append(chart('calibration'))
    curve.drop(columns='bin').to_csv(OUT/'champion_test_calibration_bins.csv',index=False)
    rows=[]
    for cycle,g in iterations[iterations.experiment.eq('main')].groupby('cycle'):
        rows.append({'cycle':int(cycle),'candidate_features':prep['stages'][str(cycle)],'new_engineered':0 if cycle==0 else prep['stages'][str(cycle)]-prep['stages'][str(cycle-1)],'versions':len(g),'versions_passing_validation':int(g.gates_pass.sum()),'best_validation_ap':float(g.ap.max())})
    cycles=pd.DataFrame(rows);cycles.to_csv(OUT/'cycle_summary.csv',index=False)
    replaym=pd.read_csv(OUT/'full_base_replay_metrics.csv')
    coverage=summary['backtest_rows_per_family'];groups=pd.read_csv(OUT/'test_fixture_first_signal.csv');fixture_metrics=[]
    for f,g in groups.groupby('family'):
        signals=g[g.has_signal];tp=signals.first_signal_y.sum()
        fixture_metrics.append({'family':f,'fixtures':len(g),'signaled_fixtures':len(signals),'first_signal_precision':float(tp/len(signals)) if len(signals) else 0.,'positive_fixtures':int(g.positive_fixture.sum()),'first_signal_recall':float(tp/g.positive_fixture.sum()) if g.positive_fixture.sum() else 0.})
    fm=pd.DataFrame(fixture_metrics);fm.to_csv(OUT/'fixture_level_metrics.csv',index=False)
    sections=[
      '<h1>Evaluación de SportEdge V6 result_to_draw</h1><p>11 de octubre de 2026. Construcción, selección temporal, backtesting y servicio HTTP desacoplado.</p>'+executive,
      '<h2>Definición y archivos analizados</h2><p>Se analizaron el informe DOCX v20260827 vs v20260828, el cuadro XLSM V4.1 vs V4 y los campos PREDICTORA=SI del diccionario XLSX. El informe previo recomienda selección dentro de entrenamiento, folds temporales, imputación y encoding por fold, control de redundancia, calibración separada y contraste con prueba futura. Su V4.1 de empate alcanzó 50,0% de precisión y 40,0% de recall en validación pero cero señales en test. El V4 anterior informó 50,3% y 34,5% en selección, sin una prueba posterior comparable.</p><p>El XLSM de comparación contiene la hoja Version_Anterior_V4(PROD), con 69 entradas, 72 ingenierías y 148 columnas físicas. Es evidencia histórica, no una especificación de los 183 predictores actuales. La definición de target de la última fila del XLSX suministrado corresponde a home_score_to_increase. Sólo se usaron sus 183 marcas SI para predictores. Las etiquetas de result_to_draw se preservaron del CSV y de su auditoría contra el XLSM específico de ese target.</p><p><strong>Target usado:</strong> igualación posterior válida desde diferencia ±1, no revertida por correcciones de marcador, y empate en el cierre disponible del mismo grupo (id, market_id). Sin FT, el cierre alternativo es el último registro si el grupo alcanza minuto ≥90. La fuente no contiene capturas FT; no se verifica externamente el resultado oficial. Pendientes se mantienen como NULL.</p>',
      f"<h2>Base y balanceo</h2><p>La base conserva {prep['rows']:,} filas, 222 columnas y {prep['fixtures']} partidos. Tiene {prep['positive_rows']:,} positivos y {prep['pending']} pendientes. El entrenamiento supervisado elegible utiliza {prep['supervised_rows']:,} snapshots de {prep['supervised_fixtures']} partidos antes de purgar las etiquetas que no estaban disponibles en la siguiente frontera. Los estados de diferencia distinta de ±1 tienen target determinístico negativo y no se incluyen para inflar el rendimiento del clasificador.</p><p>Los pesos de entrenamiento igualan la contribución agregada por partido y comparan balance 0, parcial (exponente 0,5) y completo (exponente 1). No se altera la distribución ni se sobremuestrea calibración, validación o test. Forzar una validación 50/50 distorsionaría la precisión y la probabilidad operacional.</p>"+table(p.reset_index(),percent=['prevalence'])+plots[2],
      '<h2>Tres ciclos de ingeniería y selección</h2><p>Se generaron 136 variables causales desde el snapshot. El primer ciclo orienta volumen, calidad, eficiencia y fortaleza al equipo que debe empatar. El segundo añade actividad de 5 y 10 minutos, aceleración y presión relativa. El tercero cruza amenaza competidora, tarjetas y exposición con tiempo anunciado o una aproximación fija al minuto 95. Estas aproximaciones no usan el minuto final real ni un evento futuro.</p><p>Cada ciclo calcula Spearman, información mutua y un proxy Extra Trees sólo en entrenamiento; elimina constantes, ausencia ≥98% y redundancia Spearman >0,995. Compara límites de 35, 70 y 120 variables, flags de ausencia y categorías de liga/cluster aprendidas en entrenamiento. Cinco folds vuelven a ajustar este proceso desde cero. Los archivos feature_catalog.json, effective_model_variables.csv y feature_stability.csv distinguen candidatas, fórmulas y variables realmente utilizadas. No se atribuye significado causal a correlación o importancia.</p>'+table(cycles,decimals=['best_validation_ap'])+plots[3],
      '<h2>Búsqueda y calibración</h2><p>Siete familias evaluaron 40 configuraciones de estimador por cinco calibraciones, equivalentes a 200 versiones por familia y 1.400 versiones principales. Se comparan identidad, sigmoid, isotonic, beta y sigmoid con minuto. El calibrador se ajusta en un bloque posterior al entrenamiento; el umbral se selecciona en un tercer bloque. Calibradores con pendiente inversa se sustituyen por la prevalencia constante. El ensamble soft voting compara 64 combinaciones de pesos sin consultar test. Los 64 escenarios se repiten de manera anidada dentro de cada fold.</p><p>La selección prioriza precisión >50% y recall >25%. Entre umbrales factibles maximiza precisión. Cuando sólo se cumple precisión, maximiza recall manteniendo esa precisión y deja constancia de la relajación. Exige al menos 30 snapshots y 10 partidos con señal. Cuando no existe un umbral con precisión soportada, fija 1,000001 para abstenerse. El soporte mínimo se mide en selección y no garantiza precisión futura.</p>'+table(mainm[~mainm.partition.str.contains('fixture_weighted')][['family','partition','precision','recall','f1','ap','brier','probability_mean','probability_signal_mean','threshold','tp','fp','signal_fixtures']],percent=['precision','recall','f1','ap','probability_mean','probability_signal_mean'],decimals=['brier','threshold']),
      '<h2>Backtesting temporal y prueba independiente</h2><p>Los cinco folds usan ventanas expansivas. Cada fold vuelve a seleccionar modelo, calibración y umbral usando exclusivamente sus bloques anteriores. Se evaluaron ocho configuraciones por cinco calibraciones y familia por fold, otras 1.400 versiones. No se reutilizan las decisiones de la búsqueda final para simular decisiones históricas. El primer 30% temporal es calentamiento sin predicciones fuera de muestra. La cobertura del backtest de desarrollo es de '+str(coverage)+' snapshots por familia; la prueba final añade '+str(summary['test_rows'])+' snapshots de '+str(summary['test_fixture_count'])+' partidos.</p>'+table(nm[['family','rows','precision','recall','f1','ap','brier','signal_rate']],percent=['precision','recall','f1','ap','signal_rate'],decimals=['brier'])+plots[1]+'<p>Se congeló familia y umbral en selection_frozen_before_test.json antes de calcular las métricas de prueba. El test no cambia el campeón ni dispara reentrenamiento. Las métricas de todos los finalistas sirven para diagnóstico. Los intervalos bootstrap remuestrean partidos completos, con 1.000 réplicas, para respetar la dependencia entre snapshots.</p>'+plots[0]+plots[4]+table(fm,percent=['first_signal_precision','first_signal_recall']),
      '<h2>Comparador previo y replay de toda la base</h2><p>El V4 activo hist_gradient_boosting_S06 se evaluó con su umbral original 0,7757737873, sin recalibrarlo ni seleccionar un umbral nuevo. Se verificó el hash del artefacto local y del contenedor activo. Se contrasta contra las etiquetas actuales, que requieren conservar el empate al cierre. Su objetivo histórico y cohortes de entrenamiento difieren, por lo que la comparación describe su comportamiento ante este contrato; no demuestra por sí sola superioridad universal.</p>'+table(incumbent[['partition','precision','recall','f1','ap','brier']] if not incumbent.empty else pd.DataFrame(),percent=['precision','recall','f1','ap'],decimals=['brier'])+'<p>backtesting_base_completa.csv conserva exactamente las filas, columnas, valores y orden del CSV fuente, y añade scores, probabilidades, umbrales y decisiones de los ocho finalistas. Incluye columnas separadas del backtest anidado. Los casos pendientes reciben predicción, pero su etiqueta no se convierte en FALSE. El replay contiene entrenamiento, calibración y selección, de modo que su agregado no es una estimación de generalización. La precisión sobre toda la base también incluye negativos determinísticos y no reemplaza la precisión sobre estados elegibles.</p>'+table(replaym[['family','scope','rows','precision','recall','f1','probability_mean','probability_signal_mean','signal_rate']],percent=['precision','recall','f1','probability_mean','probability_signal_mean','signal_rate']),
      '<h2>Implementación y límites operativos</h2><p>El servicio se identifica como result_to_draw y usa el contenedor sportedge_v6_result_to_draw, en la red existente sportedge_v6. El endpoint POST /v1/models/result_to_draw/predict permite seleccionar familia y recibe los 183 predictores y metadatos del snapshot. Devuelve raw_model_score, probability, threshold, signal y actionable_signal junto al hash y versión. La persistencia SQLite durable guarda entrada y resultado; request_id garantiza reintentos idempotentes y rechaza reutilización con otro contenido. El acceso requiere token y el puerto del host se limita a 127.0.0.1:8792.</p><p>El ensamble seleccionado combina 75% HGB hist_gradient_boosting_006_identity y 25% CatBoost catboost_036_identity. En el CSV de replay, los estados no elegibles tienen probability=0 por la definición determinística del target y raw_score vacío. En la API, fuera del horizonte se registra probability=null para indicar que no se ejecutó el clasificador.</p><p>La habilitación requiere cumplir los gates tanto en validación como en backtest de desarrollo y test. El servicio permanece disponible para investigación aunque un modelo no los cumpla. Se verificó una llamada real desde sportedge-v6-api-1 y la supervivencia de un resultado después de reiniciar el contenedor nuevo. Los workers actuales mantienen un contrato específico de home_score_to_increase; se entrega un cliente independiente para invocar este endpoint, sin asignar un target diferente a ese worker. Esta entrega no conecta automáticamente el collector a result_to_draw ni envía notificaciones. Una probabilidad alta no significa certeza.</p><p>Limitaciones: cierre alternativo observado sin reconciliación externa FT; sólo 117 partidos con alguna etiqueta positiva en la fuente; deriva de prevalencia entre ventanas; posibles correlaciones entre registros de mercados del mismo fixture; ausencia de variables y ligas no vistas; optimismo residual de búsqueda múltiple dentro del desarrollo. Permutation importance conserva las demás derivadas correlacionadas y es un diagnóstico, no efecto causal.</p>',
      '<h2>Archivos de auditoría</h2><p>Se adjuntan métricas por partición y por familia, todas las versiones con parámetros, evolución por ciclo, matrices de correlación, perfil de variables, ranking y estabilidad, bootstrap, subgrupos por liga/cluster, señal inicial por partido, contratos y validaciones HTTP. El repositorio conserva código, protocolo, modelos y reportes resumidos; el CSV completo y los datos fuente permanecen en la carpeta de investigación.</p>'
    ]
    content='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evaluación V6 result_to_draw</title><style>body{font:16px/1.55 Arial,sans-serif;color:#1b2734;background:#f3f5f7;margin:0}main{max-width:1180px;margin:30px auto;padding:32px;background:white}h1,h2{color:#152c45;line-height:1.2}h1{font-size:30px}h2{font-size:22px;margin-top:38px}.lead{font-size:20px;padding:20px;border-left:4px solid #355f89;background:#edf3f8}table{border-collapse:collapse;font-size:12px;display:block;overflow:auto;max-width:100%;margin:20px 0}th{background:#183a59;color:white;white-space:nowrap}td,th{padding:8px 10px;text-align:right;border-bottom:1px solid #dbe1e7}td:first-child,th:first-child{text-align:left}tr:nth-child(even){background:#f4f6f8}img{max-width:100%;height:auto;margin:18px 0}code{font-size:13px}@media print{body{background:white}main{margin:0;padding:0}h2{break-after:avoid}table,img{break-inside:avoid}}</style><main>'+''.join(sections)+'</main></html>'
    (OUT/'Informe_V6_result_to_draw.html').write_text(content,encoding='utf8')
    # JSON intermediates for the artifact-tool workbook; typed numbers remain numbers.
    parts={'Resumen':pd.DataFrame([{'Modelo':f,'Precision test':v['test']['precision'],'Recall test':v['test']['recall'],'F1 test':v['test']['f1'],'Umbral':v['threshold'],'Probabilidad media':v['test']['probability_mean'],'Precision backtest':v['nested_development_backtesting']['precision'],'Recall backtest':v['nested_development_backtesting']['recall'],'Aprobado':v['production_approved']} for f,v in reg['models'].items()]),'Particiones':pd.read_csv(OUT/'partitions.csv'),'Metricas':mainm[~mainm.partition.str.contains('fixture_weighted')],'Backtest temporal':bt,'Calibracion':pd.read_csv(OUT/'calibration_before_after.csv'),'Ingenieria':pd.DataFrame(json.loads((OUT/'feature_catalog.json').read_text())),'Variables finales':pd.read_csv(OUT/'effective_model_variables.csv'),'EDA':eda,'Ciclos':cycles,'Comparador V4':incumbent}
    workbook_data={k:{'columns':v.columns.tolist(),'rows':v.astype(object).where(v.notna(),None).values.tolist()} for k,v in parts.items()}
    (OUT/'workbook_data.json').write_text(json.dumps(workbook_data,ensure_ascii=False,default=str,allow_nan=False),encoding='utf8')
    for name in ['metrics_comparison.csv','nested_backtesting_metrics.csv','nested_aggregate.json','selection_frozen_before_test.json','test_bootstrap.json','completion_summary.json','calibration_before_after.csv','partitions.csv','effective_model_variables.csv','feature_catalog.json','feature_stability.csv','cycle_summary.csv','incumbent_comparison.csv']:
        if (OUT/name).exists():shutil.copy2(OUT/name,ROOT/'docs'/name)
    print('HTML report and workbook intermediates complete')

if __name__=='__main__':main()
